Here is an example Java function that uses the JFreeChart library to display a GUI histogram of a given number list:

```
import java.util.List;
import javax.swing.JFrame;
import org.jfree.chart.ChartFactory;
import org.jfree.chart.ChartPanel;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.axis.NumberAxis;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.chart.plot.XYPlot;
import org.jfree.data.statistics.SimpleHistogramBin;
import org.jfree.data.statistics.SimpleHistogramDataset;

public class HistogramGUI {

    public static void showHistogram(List<Double> list) {
        SimpleHistogramDataset dataset = new SimpleHistogramDataset("Number Distribution");
        for (double num : list) {
            dataset.addBin(new SimpleHistogramBin(num, num, true, true));
        }
        JFreeChart chart = ChartFactory.createHistogram("Histogram", "Number", "Frequency", dataset, PlotOrientation.VERTICAL, false, false, false);
        XYPlot plot = chart.getXYPlot();
        NumberAxis domain = (NumberAxis) plot.getDomainAxis();
        domain.setAutoRangeIncludesZero(false);
        JFrame frame = new JFrame("Histogram");
        frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        ChartPanel panel = new ChartPanel(chart);
        frame.setContentPane(panel);
        frame.pack();
        frame.setVisible(true);
    }

}
```

